#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"

if [[ -f .env && "${1:-}" != "--force" ]]; then
  echo "Refusing to overwrite existing .env (use --force if you really mean it)." >&2
  exit 1
fi

PYTHON="${PYTHON:-python3}"
if ! command -v "$PYTHON" >/dev/null 2>&1; then
  echo "python3 is required." >&2
  exit 1
fi

PASSWORD="$($PYTHON -c 'import secrets; print(secrets.token_urlsafe(18))')"
SECRET="$($PYTHON -c 'import secrets; print(secrets.token_hex(32))')"
EA_TOKEN="$($PYTHON -c 'import secrets; print(secrets.token_urlsafe(32))')"
umask 077
cat > .env <<ENV
# Generated by setup.sh. Keep private.
AURUM_HOST=127.0.0.1
AURUM_PORT=8080
AURUM_DATA_DIR=./data
AURUM_DASHBOARD_PASSWORD=${PASSWORD}
AURUM_SECRET_KEY=${SECRET}
AURUM_COOKIE_SECURE=false
AURUM_PAPER_BALANCE=10000
AURUM_SYMBOL=XAUUSD

# Live terminal execution is disabled until you deliberately configure and arm it.
AURUM_LIVE_ENABLED=false
AURUM_LIVE_ARM_PHRASE=ARM LIVE TRADING
AURUM_BRIDGE_URL=http://127.0.0.1:8765
AURUM_BRIDGE_TOKEN=
AURUM_BRIDGE_TIMEOUT=6
AURUM_EA_TOKEN=${EA_TOKEN}

# Optional OpenAI-compatible analyst. Empty = quant-only.
AURUM_AI_API_KEY=
AURUM_AI_BASE_URL=https://api.openai.com/v1
AURUM_AI_MODEL=gpt-4o-mini
AURUM_AI_TIMEOUT=12

AURUM_LOG_LEVEL=INFO
ENV
chmod 600 .env

cat <<TXT

AURUM AI setup complete.

  Dashboard password : ${PASSWORD}

  Local run          : ./run.sh
  Docker run         : docker compose up --build
  Dashboard          : http://localhost:8080

  The password is stored in .env (mode 600). Keep it private.
  Live trading is OFF. See README.md → "Connect MetaTrader 4" or "Connect MetaTrader 5".
  The MT4 EA token is stored privately in .env; copy it into the EA's InpToken when setting up MT4.

TXT
